      , _FIVETRAN_SYNCED
      , LOAD_DTS
      , PSA_RECORD_SOURCE
      , PSA_LOAD_DTS
      , PSA_DELETE_IND
    FROM LOGIC_S
)

, RENAME_sup as (
    SELECT
        SUPPLIER_BK
      , SUP_VENDOR_ID
      , SEGMENT_1
    FROM LOGIC_sup
)

, RENAME_A as (
    SELECT
        REC_SRC
      , BKCC
    FROM LOGIC_A
)
---- FILTER LAYER ----

, FILTER_S as (
    SELECT *
    FROM RENAME_S
)

, FILTER_A as (
    SELECT *
    FROM RENAME_A
    WHERE rec_src = 'USWIOC.ORCL.OCFPRD.AP_SUPPLIER_SITES_ALL'
)

, FILTER_sup as (
    SELECT *
    FROM RENAME_sup
)

---- JOIN LAYER ----
, JOIN_RESULT as (
    SELECT *
    FROM FILTER_S
    INNER JOIN FILTER_A
        ON '1' = '1'
    LEFT JOIN FILTER_sup
        ON FILTER_S.VENDOR_ID = SUP_VENDOR_ID
)

---- FINAL LAYER ----
